package cn.starfall.blueprint;

import java.util.List;
import net.minecraft.core.component.DataComponents;
import net.minecraft.network.chat.Component;
import net.minecraft.server.network.Filterable;
import net.minecraft.world.item.WrittenBookItem;
import net.minecraft.world.item.component.WrittenBookContent;

public final class FieldManualItem extends WrittenBookItem {
    public FieldManualItem(Properties p) {
        super(p.stacksTo(1).component(DataComponents.WRITTEN_BOOK_CONTENT, new WrittenBookContent(
                Filterable.passThrough("星落蓝图 · 营地手册"), "游子独立团 · 工务组", 0, List.of(
                page("§l从一块矿开始§r\n\n先用铁镐采赤钛矿和灰硼矿。普通熔炉每块原矿烧2份辅料。用钛硼制作探索装备，再寻找陨相晶脉；陨相需铁镐以上。\n\n整备台：上排3铁；中排石/铜/石；下排石/空/石。\n\n不需要晶料或电控板起步。"),
                page("§l辅矿到基础制造§r\n\n整备台每10秒／40kXH：赤钛原矿1＋250mB水出钛粉10；灰硼原矿1干式出硼盐10。\n\n先用普通熔炉起步，整备台可把原矿利用率提高到5倍。"),
                page("§l第一次整备§r\n\n水桶右键加入1000mB水，可加工4批。界面放入原矿和煤/木炭。\n\n每批10秒，耗水250mB、40kXH；一煤320kXH，可加工8批。\n\nG6%出5份；G12%出10份；G24%出20份。"),
                page("§l第一件有用的成品§r\n\n晶料＋铜锭→省能接头。右键装入整备台，每批36kXH。\n\n晶料上、铁锭下→工具加固扣。\n晶料左、铁锭右→盾面衬片。\n\n钛制耐磨镶片先给镐＋10%；找到陨相后可用加固扣升到＋20%。只替换等级，不相乘，不修复损耗。盾面衬片给盾＋20%。"),
                page("§l修理加固装备§r\n\n工作台或砂轮合并同类装备，保留其中的加固。\n\n工作台会清除名称与普通附魔；砂轮沿用上槽名称。\n\n铁砧以左侧为目标：把加固装备放左侧，右侧加固不转移。"),
                page("§l升级下界合金§r\n\n加固钻石镐可用原版模板和下界合金锭升级。\n\n按原等级重算下界合金基础耐久：20%级上限2437。保留损耗比例、名称与附魔。\n\n20%级镐＋耐磨镶片＋硼玻璃＋烈焰粉，可选复合强化至30%。同级不能重装。"),
                page("§l继续找矿§r\n\n铜锭＋红石＋玻璃＋硼盐→近距寻矿指示片。寻找第一块陨相矿之前就能制作。\n\n右键扫描8格球形范围，只反馈有无信号；不会显示坐标或品位，不加载远处区块。\n\n冷却2秒。原矿的品位和完整度在提示中显示。"),
                page("§l搭成基础产线§r\n\n上方漏斗投矿，侧面漏斗投煤，下方漏斗取晶料和尾砂。\n\n水可手动补入，也开放NeoForge普通水输入接口。\n\n尾砂槽最多缓存16批相同尾砂。不同品质不可强行混合。"),
                page("§l雨水补给§r\n\n4玻璃围住1铁锭→4000mB常压罐。\n\n集雨器：\n铁 玻璃 铁\n玻璃 罐 空\n木板 木板 木板\n\n露天雨天100mB/秒，放在整备台正上方可自动补水；晴天不产水。"),
                page("§l停机与搬迁§r\n\n欠燃料或堵塞时保留进度。开始一批时预留矿与水，每刻扣除相能。\n\n拆下整备台会把库存、水、余能、接头及在制批次打包；重新放置续作。\n\n罐与集雨器同样保留水量。未加载的区块不补算产量。"),
                page("§l安置点工务交付§r\n\n终端配方：纸放上中；圆石放中排三格与下中。\n\n持合格Q0晶料右键，每份换1铁；所有终端共享每日4笔。空手查看余量，不领取物资。"),
                page("§l为重建提供工具§r\n\n折桥救援之后，白灯安置点需要供水、照明与运输。整备台、升级件和雨水设备服务这些实际需求。\n\n本册只供查阅配方，冒险按主线剧情推进。"),
                page("§l普通结构材料§r\n\n2铁锭竖排→2份铁板。\n1铜锭→1份铜板。\n3铁锭横排→3组铁制固定件。\n\n黏土球经熔炉10秒→陶瓷。\n铜板＋硼盐→2份隔离基底，不再拆半份材料。"),
                page("§l单方块电动辊压机§r\n\n1铁锭→1铁板；1铜锭→1铜板。按来料自动选择，每批2秒／1000XH。\n\n上方进锭、底部出板、侧面接电，红石暂停。手工板材配方保留，可先做起步零件。\n\n机架1、活塞1、铁板2、钢2、控制板1、钢制固定件1、铜板1装配。L27提供供料箱、风机和收集箱蓝图。"),
                page("§l合金混料炉§r\n\n工作台按图摆放：\n铁 铜 铁\n石 炉 石\n石 石 石\n\n石是圆石，炉是普通熔炉。无需钢、晶料或控制板。\n\n右键打开：上方两格放3铁锭和1煤/木炭，下方燃料格另外加煤/木炭。"),
                page("§l从铁到普通钢§r\n\n混料炉每10秒把3铁＋1煤/木炭加工成3钢坯。碳料和供热燃料分别消耗。\n\n再把钢坯送普通熔炉，每件10秒烧成1普通钢。\n\n顶部进两种原料，侧面进燃料，底部取钢坯。欠料、欠燃料或满仓暂停；拆移保留在制批次。"),
                page("§l绝缘与电控§r\n\n纸＋硼盐→2份绝缘基材；小麦＋黏土球→2份粘结剂。\n\n铜＋红石＋玻璃＋绝缘＋Q0晶料→控制板。\n铁＋铜＋红石＋1份绝缘→断路保护器。\n\n陶瓷＋钛粉→2份护套；1份普通钢→钢制固定件。"),
                page("§l九宫格只放整件§r\n\n基础机架：4铁锭、2铜锭、2圆石、1组铁制固定件无序合成。每件各占一格，正好9格。\n\n2铁＋玻璃＋1份绝缘→封存盒，当前只作装配材料。\n\n配方中的3铁要摆3格；不会在一格中自动扣3件，不用称量或拆分余料。"),
                page("§l陨相带来工业提升§r\n\n首台整备与混料可先用煤、手动补水起步。\n\n控制板、六类基础发电机、Ⅰ级提速和扩批模块均需Q0晶料。并列炉、自动合成和抽取器通过控制板继承陨相门槛。\n\n后续精密材料与装备强化继续使用陨相。"),
                page("§l余烬多燃料§r\n\n余烬机组接受原版及模组认可的熔炉燃料。每燃烧刻转为200XH，最高输出500XH/t。煤／木炭仍是每份320kXH。\n\n岩浆桶提供4,000kXH，空桶进入成品槽，可从底部取走；成品槽放不下容器时不耗新燃料。"),
                page("§l熔流发电§r\n\n熔流发电机须邻接流动岩浆，岩浆源本身不触发。每股追溯源共享200XH/t，同源多轮不叠加。水不能驱动熔流机。\n\n它不消耗或抽取岩浆，仅利用流态；通过电缆连接用电设备。"),
                page("§l地热发电§r\n\n地热机只看正下方一格：点燃篝火40、点燃灵魂篝火60、岩浆块80、岩浆源160XH/t。\n\n熄灭篝火或流动岩浆无效，不叠加周围热源。热源不消耗，是简化热源利用，并非温差模拟。"),
                page("§l库存式自动合成§r\n\n右上样品槽放入目标成品，只选3×3工作台配方。样品保留不消耗，可取回；箭头切换同物品的不同方案。\n\n右侧九宫格显示材料、成品数量和方案序号，悬停可看物品名称；仅供预览。\n\n材料放原料库存，无需照图摆放。54格分6页，每批2秒、4000XH。"),
                page("§l让流水线持续生产§r\n\n自动合成台顶部和侧面进原料，底部取出成品与容器余物。为余物留出输出空间；欠料、欠能、堵塞时暂停。\n\n普通配方按原规则检查品质和组件。数据包数量配方可声明超过64份或超过9种原料；容量和输出格仍有限。"),
                page("§l混凝土流水线§r\n\n自动合成台选择同色粉末：4沙＋4沙砾＋1染料出8份。\n\n整备台统一原料区直接放粉末，无需切模式；8同色粉末＋1000mB水，2秒／4000XH出8混凝土。原矿也能在同一台处理。"),
                page("§l2×2电动采石机§r\n\n铁板、钢基材、机架、控制板、钢制固定件与铁镐装配。一个机器物品放置成四格，占地须留空。\n\n四格下方铺石头或其他基础岩层；前方两格留空。供电后每10秒／4000XH产4圆石，不挖地、不产矿、不依赖刷石结构。后侧出料。"),
                page("§l通用辊式破碎机§r\n\n2×2整体设备，铁板、钢基材、机架、电控、固定件与活塞装配。\n\n按来料自动加工，每批2秒／2000XH：圆石→沙砾；沙砾→沙子；骨头→骨粉6；烈焰棒→烈焰粉3。\n\n骨块→骨粉9，砂岩→沙4，红砂岩→红沙4，萤石→粉4，石英块→石英4，紫水晶块→碎片4。"),
                page("§l不用补料的建材线§r\n\n施工器扫描目录选择L26，放入建筑材料并建造。培养机首次放泥土与铃兰样本，两者保留。\n\n风机要露天；凝露供水，两条采石支路分别制沙砾和沙子，自动制染料、粉末并水化成混凝土。\n\n无需补煤或沙砾。满仓和红石暂停，区块未加载不生产。"),
                page("§l连接供水与成品箱§r\n\n自动台→朝下漏斗→整备台顶部→底部漏斗→成品箱。远送先过缓存箱，再由水平抽取器和导管送顶部原料口；整备台侧面只进燃料。\n\n泵和水管供水，电缆供电；单漏斗限150件／分钟，缺水、断电、堵塞暂停并保存批次。"),
                page("§l植物培养机§r\n\n环境、样本、水桶分别放前三槽。环境与样本保留，每批20秒、250mB水、8000XH；一桶水可供四批，空桶进入成品槽。\n\n上方投入，水管与电缆连接机器，底部取产品与空桶。"),
                page("§l选择培养环境§r\n\n作物与树苗用泥土／草方块；仙人掌用沙，甘蔗可用沙或土。海带与海泡菜用沙／砂砾／黏土等并持续供水。\n\n可可需丛林木，下界疣需灵魂沙，菌类需对应菌岩。样本先在世界取得。"),
                page("§l下界、末地与珊瑚§r\n\n灵魂沙＋下界疣→疣2。末地石＋紫颂花→果2＋花1；紫颂植株→果2。\n\n15种活珊瑚／扇／块用水生基质产同种2；死珊瑚无效。绯红／诡异菌在对应菌岩上产菌2和菌柄2。"),
                page("§l培养产物§r\n\n默认每批2个产物：种子产作物、树苗产对应原木，其他植物繁殖自身。南瓜每批1个、西瓜4片、竹子4个。\n\n在制不能取换样本环境；断电、停机或堵塞暂停，保存后续作。无离线产出。"),
                page("§l蓝图一键施工§r\n\n纸＋蓝色染料制作设计图。放入施工器，点击扫描目录，点选L25、L26等蓝图。材料箱或相邻箱备齐建材后开始建造。大型机器四格只扣一个机器物品。\n\n创造施工核心放材料格可免材料；设计图与核心保留。起点在施工器前2格，红石暂停。"),
                page("§l测绘与分享§r\n\n木棍＋铁锭＋蓝色染料制作测绘笔。背包准备空白设计图，右键两个角记录布局，潜行右键重选。\n\n施工器可导出.sfbp.json文件分享；对方放入blueprints文件夹导入。只记录结构和工艺设置，不复制库存、水或电。HTML手册也能下载产线图。"),
                page("§l未来维度预留§r\n\n澄海星与林海联盟等待未来Minecraft官方新维度更新后再适配。\n\n月络已从末地移除；月络进口、灵相材料与法杖坯暂不开放。现有维度不充当替代入口。"),
                page("§l当前版本范围§r\n\n公共基础整备、CB-01至05、普通结构与电控材料、基础机架、合金混料炉及营地雨水补给已实现。\n\n基础能源、物流、库存合成、并列冶炼及公共精制已接入。剧情人物与任务、未来官方新维度内容仍待接入。\n\n自然矿分布尚未通过20种子稀有度校准。")
        ), true)));
    }
    private static Filterable<Component> page(String text) { return Filterable.passThrough(Component.literal(text)); }
}
